/* Human Movement OS v1.0.0 | local-first, framework-free. */
(function(){
'use strict';
const P=MovementProgramme,T=MovementTimer,KEY='dop.humanmovement.v1',TRAINER_KEY='dop.hmo.trainer.v02',BRIDGE_KEY='dop.hmo.bridge.v03';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const localDate=d=>{d=d||new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const dateLabel=iso=>new Date(iso).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'});
const num=(v,lo,hi,fallback)=>Number.isFinite(Number(v))&&Number(v)>=lo&&Number(v)<=hi?Number(v):fallback;
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',plan:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M4 11h16m-11 4h2m3 0h2m-7 3h2"/>',timer:'<circle cx="12" cy="13" r="8"/><path d="M12 9v5l3 2M9 2h6m-3 0v3m7 1 2 2"/>',library:'<path d="M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v16h-6a4 4 0 0 0-3 1 4 4 0 0 0-3-1H3zM12 6v15"/>',progress:'<path d="M4 20V5m0 15h17M8 16v-4m5 4V8m5 8V4"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',play:'<path d="m8 4 12 8-12 8z"/>',pause:'<path d="M8 4v16M16 4v16"/>',check:'<path d="m5 12 4 4L20 5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sound:'<path d="M3 9h4l5-5v16l-5-5H3zM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',mute:'<path d="M3 9h4l5-5v16l-5-5H3zM16 9l5 6m0-6-5 6"/>',bone:'<path d="m8 7 9 9a3 3 0 1 1-1 4 3 3 0 1 1-4-4L5 9A3 3 0 1 1 4 5a3 3 0 1 1 4 2Z"/>',strength:'<path d="m4 6 4 4m8 4 4 4M6 4l4 4M14 16l4 4M3 8l5-5m8 18 5-5M8 12l4-4 4 4-4 4z"/>',tendon:'<path d="M6 3c0 6 12 12 12 18M18 3C18 9 6 15 6 21M9 3c0 6 6 12 6 18"/>',mobility:'<circle cx="12" cy="5" r="2"/><path d="m4 9 8 2 8-2M12 11v5m0 0-5 5m5-5 5 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.5"/>',plus:'<path d="M12 4v16M4 12h16"/>',minus:'<path d="M4 12h16"/>',reset:'<path d="M4 5v6h6M5 10a8 8 0 1 1 0 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',skip:'<path d="m5 5 10 7-10 7zM19 4v16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',heart:'<path d="M12 21 3 12C-2 4 7 0 12 6c5-6 14-2 9 6z"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>'};
function I(name,cls=''){return `<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24">${icons[name]||icons.activity}</svg>`;}
const defaults=()=>({schema:KEY,version:1,week:1,day:'mon',readiness:'ready',settings:{sound:false,volume:.65,haptics:false,wake:true,large:false,budget:45,equipment:'gym',skills:['handstand','compression'],experienced:false,impact:false,onboarded:false},history:[],benchmarks:[],aerobic:[],active:null,free:null});
let storageOK=true,storageError='',state=defaults();
function validHistory(h){
 const bounded=(x,n)=>typeof x==='string'&&x.length<=n;
 return Array.isArray(h)&&h.length<=2000&&h.every(x=>x&&bounded(x.id,200)&&bounded(x.date,40)&&Number.isFinite(Date.parse(x.date))&&bounded(x.title,200)
  &&Number.isInteger(x.week)&&x.week>=1&&x.week<=52&&P.DAYS.some(d=>d.id===x.day)&&['main','recovery'].includes(x.type)
  &&typeof x.completed==='boolean'&&/^\d{4}-\d{2}-\d{2}$/.test(x.localDate)&&bounded(x.localDate,10)
  &&Number.isFinite(x.duration)&&x.duration>=0&&x.duration<=604800
  &&(x.notes===undefined||bounded(x.notes,1000))&&(x.discomfort===undefined||['','yes','no'].includes(x.discomfort))
  &&(x.nextMorning===null||x.nextMorning===undefined||['Same or better','More sore than usual','New or worsening pain'].includes(x.nextMorning))
  &&Array.isArray(x.logs)&&x.logs.length<=1000&&x.logs.every(l=>l&&P.EX[l.id]&&bounded(l.name,200)&&Number.isInteger(l.set)&&l.set>=1&&l.set<=100
   &&['','Left','Right'].includes(l.side)&&Number.isFinite(l.reps)&&l.reps>=0&&l.reps<=1000&&Number.isFinite(l.seconds)&&l.seconds>=0&&l.seconds<=86400
   &&Number.isFinite(l.targetSeconds)&&l.targetSeconds>=0&&l.targetSeconds<=86400&&Number.isFinite(l.targetReps)&&l.targetReps>=0&&l.targetReps<=1000
   &&['Warm-up','Skill','Strength','Power','Movement','Mobility','Flexibility','Cool-down'].includes(l.block)
   &&(l.load===null||Number.isFinite(l.load)&&l.load>=0&&l.load<=2000))
  &&(x.skipped===undefined||Array.isArray(x.skipped)&&x.skipped.length<=200&&x.skipped.every(y=>y&&P.EX[y.id]&&bounded(y.name,200))));
}
function normaliseSettings(x){const d=defaults().settings; x=x&&typeof x==='object'?x:{};
  for(const key of ['sound','haptics','wake','large','experienced','impact','onboarded'])if(typeof x[key]==='boolean')d[key]=x[key];
  d.volume=num(x.volume,0,1,d.volume); d.budget=[45,60].includes(x.budget)?x.budget:45;d.equipment=x.equipment==='home'?'home':'gym';
  if(Array.isArray(x.skills)){const a=[...new Set(x.skills.filter(k=>P.SKILLS[k]))].slice(0,2);if(a.length)d.skills=a;}
  return d;
}
function validActive(a){return a&&typeof a.id==='string'&&Number.isFinite(a.started)&&Number.isFinite(a.pausedMs)&&a.pausedMs>=0&&Array.isArray(a.steps)&&a.steps.length>0&&a.steps.length<=1000&&a.steps.every(s=>P.EX[s.id]&&Number.isInteger(s.gid)&&Number.isFinite(s.seconds)&&Number.isFinite(s.reps))&&Number.isInteger(a.i)&&a.i>=0&&a.i<=a.steps.length&&Array.isArray(a.logs)&&['ready','prep','work','confirm','rest','finished'].includes(a.stage);}
try{const raw=localStorage.getItem(KEY);if(raw){const x=JSON.parse(raw);if(x.schema!==KEY||!validHistory(x.history))throw Error('Unrecognised saved data');state={...defaults(),week:P.week(x.week).number,day:P.DAYS.some(d=>d.id===x.day)?x.day:'mon',readiness:['ready','lighter','rest'].includes(x.readiness)?x.readiness:'ready',settings:normaliseSettings(x.settings),history:x.history,
  benchmarks:Array.isArray(x.benchmarks)?x.benchmarks.slice(-500):[],aerobic:Array.isArray(x.aerobic)?x.aerobic.filter(v=>v&&Number.isFinite(v.minutes)&&v.minutes>=0&&v.minutes<=1440&&typeof v.date==='string').slice(-2000):[],active:validActive(x.active)?x.active:null,free:x.free&&['countdown','stopwatch','intervals'].includes(x.free.mode)?x.free:null};}}
catch(e){storageOK=false;storageError='Saved data could not be loaded. Existing browser data has not been overwritten. Export or clear it in Settings.';}
let view='today',previewWeek=state.week,selectedPhase=P.week(state.week).phase;
let clock=new T.Clock(state.active?.clock),freeClock=new T.Clock(state.free?.clock);
let wakeSentinel=null,wakePending=false,audio=null,toastJob=null,lastAction='',lastActionAt=0,hiddenAt=null;
let freeConfig=state.free||{mode:'countdown',seconds:90,work:30,rest:60,rounds:5,round:1,segment:'work',started:false,pending:false};
let pendingImport=null,finishWasComplete=false,libraryFilter='all';
const query=new URLSearchParams(location.search),assignedClientId=query.get('client')||window.HMO_CLIENT_ID||'';
let assignedClient=null;
function readTrainerAssignment(){
 if(!assignedClientId)return null;
 try{const ts=JSON.parse(localStorage.getItem(TRAINER_KEY)||'null');const c=ts?.clients?.find(x=>x.id===assignedClientId);if(!c)return null;assignedClient={id:c.id,name:c.name,email:c.email,program:c.program,week:Math.max(1,Math.min(52,Number(c.week)||1)),status:c.status};state.week=assignedClient.week;return assignedClient;}catch{return null;}
}
readTrainerAssignment();
function publishWorkoutSummary(h,plannedSets){
 if(!assignedClient)return;
 const summary={id:h.id,clientId:assignedClient.id,clientName:assignedClient.name,week:h.week,day:h.day,title:h.title,completed:h.completed,completedAt:h.date,durationSeconds:h.duration,completedSets:h.logs.length,plannedSets:plannedSets||0,effort:h.effort,discomfort:h.discomfort||'',notes:h.notes||''};
 try{const items=JSON.parse(localStorage.getItem(BRIDGE_KEY)||'[]');if(!items.some(x=>x.id===summary.id)){items.unshift(summary);localStorage.setItem(BRIDGE_KEY,JSON.stringify(items.slice(0,2000)));}}catch(e){}
 if(window.HMOBackend?.mode==='supabase'&&window.HMOBackend?.saveWorkoutSummary)window.HMOBackend.saveWorkoutSummary(summary).catch(()=>{});
}
if(state.active){state.active.variations=state.active.variations||{};state.active.skipped=state.active.skipped||[];state.active.input=state.active.input||{};state.active.last=state.active.last||null;}
function persist(){if(state.active)state.active.clock=clock.snapshot();state.free={...freeConfig,clock:freeClock.snapshot()};
  if(!storageOK)return false;try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch(e){storageOK=false;storageError='Browser storage is unavailable or full. New work is kept in this tab only. Export a backup before closing.';updateStorageWarning();return false;}}
function toast(message){const t=$('#toast');t.textContent=message;t.hidden=false;clearTimeout(toastJob);toastJob=setTimeout(()=>t.hidden=true,5200);}
function announce(s){$('#announcer').textContent=s;}
function updateStorageWarning(){const b=$('#storage-warning');b.hidden=storageOK;b.textContent=storageError;}
function modal(title,body,actions=''){const d=$('#modal');$('#modal-content').innerHTML=`<div class="dialog-body"><div class="dialog-header"><h2 id="dialog-title">${title}</h2><button class="iconbtn" data-action="close-modal" aria-label="Close dialog">${I('close')}</button></div>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}</div>`;d.setAttribute('aria-labelledby','dialog-title');if(!d.open)d.showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();}
function navigate(target){if(view==='workout'&&state.active)readLogInputs();view=target;document.body.classList.toggle('workout-mode',view==='workout');render();window.scrollTo(0,0);}
function opts(){return {...state.settings,readiness:state.readiness};}
function plan(n=state.week,day=state.day){return P.makeWorkout(n,day,opts());}
function totalStats(){return {sessions:state.history.filter(h=>h.completed&&h.type==='main').length,sets:state.history.reduce((n,h)=>n+h.logs.filter(l=>!['Warm-up','Cool-down','Flexibility','Mobility'].includes(l.block)).length,0),minutes:Math.round(state.history.reduce((n,h)=>n+h.duration,0)/60)};}
function recentStats(){const cutoff=Date.now()-7*86400000;return state.history.filter(h=>Date.parse(h.date)>=cutoff);}
function phaseLabel(n){return P.PHASES[P.week(n).phase-1];}
function renderNav(){const titles={today:'Today',programme:'Programme',timer:'Workout timer',library:'Movement library',progress:'Your progress',settings:'Settings and evidence'};
  $('#nav-desktop').innerHTML=[['today','home','Today'],['programme','plan','Programme'],['timer','timer','Workout timer'],['library','library','Movement library'],['progress','progress','Progress'],['settings','settings','Settings']].map(([id,ic,text])=>`<button class="nav-item ${view===id?'active':''} ${id==='settings'?'nav-gap':''}" data-action="nav" data-view="${id}" ${view===id?'aria-current="page"':''}>${I(ic)}${text}</button>`).join('');
  $('#nav-mobile').innerHTML=[['today','home','Today'],['programme','plan','Plan'],['timer','timer','Timer'],['progress','progress','Progress']].map(([id,ic,text])=>`<button class="${view===id?'active':''}" data-action="nav" data-view="${id}" ${view===id?'aria-current="page"':''}>${I(ic)}${text}</button>`).join('');
  $('#context-title').textContent=titles[view]||'Workout';$('#sound-top').innerHTML=I(state.settings.sound?'sound':'mute');$('#sound-top').setAttribute('aria-label',state.settings.sound?'Turn sound off':'Turn sound on');
  $('#connection').textContent=location.protocol==='file:'?'Local file':navigator.onLine?'Local-first':'Offline';document.body.classList.toggle('large-type',state.settings.large);updateStorageWarning();
}
function pageHeader(eyebrow,title,desc,actions=''){return `<header class="page-top ${actions?'between':''}"><div><p class="eyebrow">${eyebrow}</p><h1 class="greeting">${title}</h1><p class="header-desc">${desc}</p></div>${actions}</header>`;}
function resumeBanner(){return state.active&&view!=='workout'?`<div class="notice resume-banner between"><div><strong class="callout-title">Your workout is still here.</strong><span>${esc(state.active.title)} · ${state.active.logs.length} sets logged</span></div><button class="btn primary" data-action="resume-workout">Resume ${I('arrow')}</button></div>`:'';}
function render(){renderNav();const screens={today:renderToday,programme:renderProgramme,timer:renderTimer,library:renderLibrary,progress:renderProgress,settings:renderSettings,workout:renderWorkout};$('#app').innerHTML=resumeBanner()+(screens[view]||renderToday)();paintClock();}
function renderToday(){const w=P.week(state.week),ph=phaseLabel(state.week),pl=plan(),d=P.DAYS.find(d=>d.id===state.day),s=totalStats();const recent=recentStats();
  const review=state.history.find(h=>!h.nextMorning&&Date.now()-Date.parse(h.date)>=12*3600000);
  return pageHeader(assignedClient?'COACHED WORKOUT / HUMAN MOVEMENT OS':'DE-OMEGA-POINT / HUMAN MOVEMENT OS',assignedClient?`Welcome, ${esc(assignedClient.name)}.`:'Train for life.',assignedClient?`Trainer-assigned programme · Week ${assignedClient.week}. Complete the session and your trainer dashboard will update.`:'Strength. Freedom of movement. One session at a time.')+
  (assignedClient?`<div class="notice" style="margin-bottom:20px"><b>Trainer connected</b><br>Your assigned week is controlled from Trainer Admin. Workout results sync back after you save the session.</div>`:'')+
  (review?`<div class="notice amber between" style="margin-bottom:20px"><div><b>Next-day check-in</b><br>How do you feel after ${esc(review.title.toLowerCase())}?</div><button class="btn secondary" data-action="checkin" data-id="${esc(review.id)}">Check in</button></div>`:'')+
  `<div class="cols"><div class="stack"><section class="card hero"><div class="hero-orbit"></div><span class="phase-marker">0${ph.id}</span><div class="hero-content"><div class="row wrap"><span class="pill green">WEEK ${w.number} / 52</span><span class="eyebrow">${esc(ph.title)}</span>${w.deload?'<span class="pill amber">Lighter week</span>':''}</div><h2>${state.readiness==='rest'?'Recovery is<br>the work today.':esc(d.title)}</h2><div class="hero-meta"><span>${I('timer')} ${pl.estimatedMinutes} min + setup</span><span>${pl.items.length} movements</span><span>${pl.type==='main'?'Strength + range':'Optional reset'}</span></div><div class="hero-bottom"><button class="btn primary big" data-action="start-workout" ${state.readiness==='rest'?'disabled':''}>${I('play')} ${pl.type==='main'?'Start workout':'Start easy reset'}</button><button class="btn text" data-action="preview">View session ${I('arrow')}</button></div></div></section>
  <section class="card"><div class="section-head"><h2>Your week</h2><button class="btn text small" data-action="nav" data-view="programme">Week ${w.number} ${I('arrow')}</button></div><div class="weekstrip">${P.DAYS.map(day=>`<button class="daychip ${state.day===day.id?'active':''} ${state.history.some(h=>h.week===state.week&&h.day===day.id&&h.completed)?'done':''}" data-action="day" data-day="${day.id}" aria-label="${day.short}: ${day.title}" aria-pressed="${state.day===day.id}"><b>${day.short}</b><span class="mini ${day.type==='rest'?'rest-dot':''}"></span></button>`).join('')}</div><div class="week-facts"><span><i class="dot accent"></i> 4 main sessions</span><span>1 optional reset</span><span>2 rest days</span></div><div class="readiness"><div class="between"><h3 class="small" style="margin:0">How are you feeling?</h3><span class="tiny muted">Choose before you start</span></div><div class="readiness-options"><button class="choice ${state.readiness==='ready'?'selected':''}" data-action="readiness" data-value="ready" aria-pressed="${state.readiness==='ready'}">Ready</button><button class="choice warn ${state.readiness==='lighter'?'selected':''}" data-action="readiness" data-value="lighter" aria-pressed="${state.readiness==='lighter'}">Go lighter</button><button class="choice stop ${state.readiness==='rest'?'selected':''}" data-action="readiness" data-value="rest" aria-pressed="${state.readiness==='rest'}">Rest today</button></div><p class="small muted" style="margin:12px 0 0">${state.readiness==='ready'?'Use familiar variations. Keep a few good repetitions in reserve.':state.readiness==='lighter'?'Fewer sets, easier variations, no optional impact. Keep the week unchanged.':'No workout will start. Rest if unwell; seek advice for new or worsening pain.'}</p></div></section>
  <div class="stat-grid"><div class="stat"><div class="number mono">${s.sessions}</div><div class="caption">Main sessions completed</div></div><div class="stat"><div class="number mono">${s.sets}</div><div class="caption">Working sets logged</div></div><div class="stat"><div class="number mono">${s.minutes}</div><div class="caption">Session minutes</div></div></div></div>
  <aside class="stack"><section class="card"><p class="eyebrow accent">THIS WEEK'S INTENTION</p><h2>${esc(w.title)}</h2><p class="small muted">${esc(w.focus)}</p><div class="sep"></div><p class="eyebrow">TRAIN THE WHOLE SYSTEM</p><div class="tissue-grid"><div class="tissue">${I('strength')}<b>Muscle</b>Strength</div><div class="tissue">${I('tendon')}<b>Tendon</b>Loading</div><div class="tissue">${I('bone')}<b>Bone</b>Resistance</div><div class="tissue">${I('mobility')}<b>Fascia</b>Movement</div></div><p class="tiny muted" style="margin:0">Training focus, not a tissue-health measurement. The app does not measure bone density or connective-tissue change.</p></section>
  <section class="card"><div class="section-head"><h2>In your session</h2><span class="pill">${state.settings.budget}-min budget</span></div><div class="mini-list">${pl.items.filter(it=>!['Warm-up','Cool-down','Flexibility'].includes(it.block)).slice(0,4).map((it,i)=>`<div class="movement-row"><span class="num mono">0${i+1}</span><div class="grow"><h3>${esc(P.EX[it.id].name)}</h3><div class="dose">${it.sets} × ${it.seconds?it.seconds+' sec':it.reps+' reps'}${P.EX[it.id].perSide?' / side':''}</div></div><button class="iconbtn" data-action="exercise" data-id="${it.id}" aria-label="Technique for ${esc(P.EX[it.id].name)}">${I('info')}</button></div>`).join('')}</div><button class="btn secondary full" style="margin-top:16px" data-action="preview">See the whole session ${I('arrow')}</button></section>
  <div class="notice">${I('shield')} <b>${assignedClient?'Trainer-linked session':'Train. Save. Repeat.'}</b><br>${assignedClient?'Your confirmed workout summary is shared with Trainer Admin in this demo.':'No account, no subscription and no cloud uploads. Your log stays in this browser.'}</div></aside></div><p class="footer-note">Week selection is manual. Moving through the calendar never automatically increases your skill level. ${recent.length} session${recent.length===1?'':'s'} logged in the last 7 days.</p>`;
}
function renderProgramme(){const w=P.week(previewWeek),ph=P.PHASES[selectedPhase-1];return pageHeader('YOUR 52-WEEK MAP','Build. Practise. Keep.','Four phases, repeatable weeks, and no race to the next skill.')+
 `<div class="phase-grid">${P.PHASES.map(p=>`<button class="phase-card ${p.id===selectedPhase?'active':''}" data-action="phase" data-id="${p.id}" aria-pressed="${p.id===selectedPhase}"><div class="number mono">0${p.id}</div><h3>${p.title}</h3><span class="small muted">Weeks ${p.start}–${p.end}</span></button>`).join('')}</div><div class="between" style="margin-bottom:19px"><div><h2 style="margin:0 0 5px">${esc(ph.full)}</h2><span class="small muted">${esc(ph.line)}</span></div><span class="pill green">Current: week ${state.week}</span></div><div class="week-grid">${P.WEEKS.filter(x=>x.phase===selectedPhase).map(x=>`<button class="week-card ${x.number===previewWeek?'selected':''}" data-action="preview-week" data-number="${x.number}" aria-pressed="${x.number===previewWeek}"><span class="wk">WEEK ${String(x.number).padStart(2,'0')}${x.number===state.week?' · CURRENT':''}</span><strong>${esc(x.title)}</strong>${x.deload?`<div class="tiny">${x.audit?'Review + lighter volume':'Lighter volume'}</div>`:''}</button>`).join('')}</div>
 <section class="card programme-detail"><div class="between"><div><p class="eyebrow accent">WEEK ${w.number} / ${phaseLabel(w.number).title.toUpperCase()}</p><h2>${esc(w.title)}</h2></div><button class="btn ${w.number===state.week?'secondary':'primary'}" data-action="use-week" data-number="${w.number}">${w.number===state.week?'Repeat this week':'Use this week'} ${I('arrow')}</button></div><p class="muted">${esc(w.focus)}</p><div class="notice ${w.deload?'amber':''}">${w.deload?'This week uses fewer sets. Review comfort and repeatability rather than maximum performance.':'Progress one variable at a time, only after repeated comfortable sessions and a settled next-day response.'} The week number is a planning label, not proof of readiness.</div><div class="day-list">${P.DAYS.map(d=>`<button data-action="programme-day" data-day="${d.id}" data-number="${w.number}"><span class="day-name">${d.short}</span><div class="grow"><strong>${d.title}</strong><div class="small muted">${d.sub}</div></div><span class="small muted">${d.type==='rest'?'Rest':P.makeWorkout(w.number,d.id,opts()).estimatedMinutes+' min'}</span>${I('arrow')}</button>`).join('')}</div></section>
 <section class="card" style="margin-top:22px"><p class="eyebrow accent">TWO PRIORITIES, NOT SIX COMPETING WORKOUTS</p><h2>Your skill focus</h2><p class="small muted">The selected priorities rotate through Tuesday and Saturday. Other patterns stay in the strength and movement work.</p><div class="skill-pills">${Object.entries(P.SKILLS).map(([k,s])=>`<button class="skill-choice ${state.settings.skills.includes(k)?'selected':''}" data-action="skill" data-key="${k}" aria-pressed="${state.settings.skills.includes(k)}">${esc(s.name)}</button>`).join('')}</div>${state.settings.skills.map(k=>`<h3 class="small">${P.SKILLS[k].name}</h3><div class="skill-path">${P.SKILLS[k].path.map(s=>`<span>${esc(s)}</span>`).join('')}</div>`).join('')}<p class="tiny muted">Skill pathways describe options, not guaranteed outcomes. One-arm eccentrics, forced shoulder stretches, loaded spinal flexion, all-out sprints and falling drills are not automatically prescribed.</p></section>`;
}
function itemRows(pl){let block='';return pl.items.map((it,i)=>{let b='';if(it.block!==block){block=it.block;b=`<div class="block-label">${block}</div>`;}return `${b}<div class="movement-row"><span class="num">${String(i+1).padStart(2,'0')}</span><div class="grow"><h3>${esc(P.EX[it.id].name)}</h3><div class="dose">${it.sets} × ${it.seconds?it.seconds+' sec':it.reps+' reps'}${P.EX[it.id].perSide?' each side':''} · ${it.rest}s rest</div></div><button class="iconbtn" data-action="exercise" data-id="${it.id}" aria-label="Technique for ${esc(P.EX[it.id].name)}">${I('info')}</button></div>`;}).join('');}
function showPreview(w=state.week,d=state.day){const pl=plan(w,d);modal('Your session',`<p class="eyebrow accent">WEEK ${w} / ${esc(pl.title)}</p><p class="small muted">About ${pl.estimatedMinutes} minutes plus equipment setup. ${esc(pl.intensity)}. Rest can always be extended.</p>${w!==state.week?'<div class="notice amber">This is a preview, not your current week. Select the week explicitly in Programme to use it.</div>':''}${itemRows(pl)}`,`<button class="btn secondary" data-action="close-modal">Close</button>${w===state.week?`<button class="btn primary" data-action="start-workout" data-day="${d}" ${state.readiness==='rest'?'disabled':''}>Start ${I('play')}</button>`:''}`);}
function showExercise(id){const e=P.EX[id];if(!e)return;if(view==='workout'&&clock.status==='running')pauseWorkout();modal(esc(e.name),`<p class="small muted">${esc(e.group)} · ${esc(e.equipment)}</p>${e.cues.map((c,i)=>`<div class="cue"><span class="cue-num">${i+1}</span><span>${esc(c)}</span></div>`).join('')}<div class="notice"><b class="callout-title">Easier option</b>${esc(e.easier)}</div><div class="notice amber" style="margin-top:14px"><b class="callout-title">Technique and comfort</b>${esc(e.watch)}</div>${view==='workout'?'<p class="small muted" style="margin-top:17px">The timer is paused while you review. Resume when you are ready.</p>':''}`,`<button class="btn primary" data-action="close-modal">Got it</button>`);}
function requestStart(day){if(state.active){closeModal();navigate('workout');return;}if(state.readiness==='rest'){toast('Rest is selected. No workout was started.');return;}
 if(day)state.day=day;if(freeConfig.started&&freeClock.status==='running'){toast('Pause or reset your standalone timer before starting a workout.');return;}
 if(!state.settings.onboarded){modal('Before your first session',`<p>This is a flexible training template, not a medical assessment or a deadline for advanced skills.</p><div class="notice amber">For a current injury, unexplained symptoms, known osteoporosis or another relevant condition, get an appropriate exercise assessment before heavy loading, impact or inversion.</div><p class="small muted" style="margin-top:16px">Stop for new or increasing pain. Chest pain, fainting or severe unusual breathlessness require urgent medical help.</p><label class="check-row"><input id="start-ack" type="checkbox"><span>I will choose movements I already control, use easier options when needed, and stop rather than train through symptoms.</span></label>`, `<button class="btn secondary" data-action="close-modal">Not now</button><button class="btn primary" data-action="confirm-start">Start session</button>`);return;}beginWorkout();}
function beginWorkout(){const pl=plan();if(!pl.steps.length)return;state.active={id:uid(),week:pl.week,phase:pl.phase,day:pl.day,title:pl.title,type:pl.type,readiness:state.readiness,deload:pl.deload,steps:pl.steps,items:pl.items,started:Date.now(),pausedMs:0,pausedAt:null,i:0,stage:'ready',logs:[],skipped:[],variations:{},input:{},last:null};clock=new T.Clock();persist();closeModal();navigate('workout');requestWake();announce('Workout ready. Start when you are ready.');}
function step(){return state.active?.steps[state.active.i];}
function currentName(s){if(!s)return '';return P.EX[s.id].name+(state.active?.variations[s.gid]?' · easier option':'');}
function exerciseCount(){const a=state.active;return a?new Set(a.steps.map(s=>s.gid)).size:0;}
function currentInput(){const a=state.active,s=step();if(!a||!s)return {reps:0,load:''};if(a.input.cursor!==a.i){const prev=[...a.logs].reverse().find(l=>l.id===s.id)||state.history.flatMap(h=>h.logs).reverse().find(l=>l.id===s.id);a.input={cursor:a.i,reps:s.reps,load:prev?.load??''};}return a.input;}
function sessionElapsed(){const a=state.active;return a?Math.max(0,(a.pausedAt||Date.now())-a.started-a.pausedMs):0;}
function renderWorkout(){const a=state.active;if(!a){setTimeout(()=>navigate('today'),0);return '';}
 const s=step(),last=a.last,rest=a.stage==='rest',isFinished=a.stage==='finished'||!s,display=rest&&last?a.steps[last.cursor]:s;
 if(isFinished)return `<div class="workout-top"><button class="btn secondary" data-action="nav" data-view="today">${I('back')} Overview</button><span class="pill green">Session review</span></div><section class="card" style="max-width:620px;margin:40px auto;text-align:center"><p class="eyebrow accent">SESSION FINISHED</p><h1>Good work.<br>Make it count.</h1><p class="muted">${a.logs.length} sets logged · ${a.skipped.length} movements skipped</p><button class="btn primary big full" data-action="finish" data-complete="true">Save session ${I('check')}</button><p class="footer-note">Only sets you confirmed are recorded. A timer reaching zero never creates a completed set on its own.</p></section>`;
 const e=P.EX[display.id],input=currentInput(),paused=clock.status==='paused';
 let actions='';
 if(a.stage==='ready')actions=`<button class="btn primary big full" data-action="start-set">${I('play')} Start ${s.sets>1?'set':'movement'}</button>`;
 else if(a.stage==='prep')actions=`<button class="btn secondary big full" data-action="pause-workout">${I(paused?'play':'pause')} ${paused?'Resume':'Pause'} preparation</button>`;
 else if(a.stage==='work'||a.stage==='confirm')actions=`<button class="btn primary big full" data-action="complete-set">${I('check')} ${a.stage==='confirm'?'Confirm set done':'Set done'}</button>${a.stage==='work'?`<button class="btn secondary full" data-action="pause-workout">${I(paused?'play':'pause')} ${paused?'Resume timer':'Pause timer'}</button>`:''}`;
 else if(rest)actions=`<div class="secondary-controls"><button class="btn secondary big" data-action="pause-workout">${I(paused?'play':'pause')} ${paused?'Resume':'Pause'}</button><button class="btn secondary big" data-action="add-rest">${I('plus')} 30 sec</button></div><button class="btn primary big full" data-action="skip-rest">Ready for next set ${I('arrow')}</button>`;
 return `<div class="workout-top"><button class="iconbtn" data-action="nav" data-view="today" aria-label="Return to overview without ending workout">${I('back')}</button><div class="grow"><div class="eyebrow">WEEK ${a.week} / ${phaseLabel(a.week).title.toUpperCase()}</div><div class="small muted">${esc(a.title)}</div></div><button class="iconbtn" data-action="toggle-sound" aria-label="${state.settings.sound?'Mute':'Enable'} sound">${I(state.settings.sound?'sound':'mute')}</button><button class="btn text small" data-action="end-early">End</button></div><progress class="session-track" value="${a.i}" max="${a.steps.length}" aria-label="Workout steps progressed"></progress><div class="workout-layout"><section class="card workout-card"><div class="workout-tag"><span class="pill ${rest?'purple':'green'}">${rest?'REST':esc(s.block.toUpperCase())}</span><span>Movement ${display.gid+1} / ${exerciseCount()}</span></div><h1>${rest?'Rest. Reset.':esc(currentName(s))}</h1><p class="target-line">${rest?`${esc(currentName(display))} · set ${display.set} logged`:`Set ${s.set} of ${s.sets}${s.side?' · '+s.side+' side':''} · <strong>${s.seconds?s.seconds+' seconds':s.reps+' reps'}</strong>`}</p>
 <div class="clock-wrap ${rest?'rest':''} ${a.stage==='confirm'?'finished':''}" id="clock-wrap"><div class="clock-label" id="clock-label">READY</div><div class="clock mono" id="main-clock" role="timer" aria-live="off">00:00</div><div class="clock-note" id="clock-note">Start when you are ready</div><progress class="clock-progress" id="clock-progress" value="0" max="100" aria-label="Current timer progress"></progress></div>
 ${!rest&&s.block==='Strength'&&!s.seconds||!rest&&s.reps>0?`<div class="log-fields"><label class="field">Reps to log${s.side?' ('+s.side.toLowerCase()+')':''}<input id="actual-reps" type="number" inputmode="numeric" min="0" max="1000" value="${input.reps}" aria-label="Actual repetitions to log"></label><label class="field">Load in kg (optional)<input id="actual-load" type="number" inputmode="decimal" min="0" max="2000" step="0.5" placeholder="Bodyweight" value="${input.load}" aria-label="External load in kilograms"></label></div>`:''}
 <div class="workout-controls">${actions}</div><div class="workout-bottom-tools">${rest?`<button class="btn text small" data-action="edit-last">Edit last set</button><button class="btn text small" data-action="undo-set">${I('reset')} Undo last set</button>`:`<button class="btn text small" data-action="make-easier">Easier option</button><button class="btn text small" data-action="skip-movement">${I('skip')} Skip movement</button>`}</div><div class="workout-status"><span id="wake-status">Screen-on: ${wakeSentinel?'active':'not active'}</span><span id="session-elapsed">Session 00:00</span><span>${storageOK?'Saved locally':'Not saved to device'}</span></div></section>
 <aside class="stack"><section class="card cue-card"><p class="eyebrow accent">${rest?'COMING NEXT':'THREE SIMPLE CUES'}</p><h2>${esc(rest?currentName(s):e.name)}</h2>${rest?`<p class="small muted">Set ${s.set} of ${s.sets}${s.side?' · '+s.side+' side':''} · ${s.seconds?s.seconds+' seconds':s.reps+' repetitions'}</p>`:''}${P.EX[(rest?s:display).id].cues.map((c,i)=>`<div class="cue"><span class="cue-num">${i+1}</span><span>${esc(c)}</span></div>`).join('')}${a.variations[(rest?s:display).gid]?`<div class="notice amber"><b class="callout-title">Easier variation selected</b>${esc(P.EX[(rest?s:display).id].easier)}</div>`:''}<button class="btn secondary full" style="margin-top:16px" data-action="exercise" data-id="${(rest?s:display).id}">${I('info')} Technique and alternatives</button><div class="next-up"><span class="eyebrow">${rest?'AFTER YOUR REST':'UP NEXT'}</span><h3>${rest?esc(currentName(s)):s.rest?'Rest · '+s.rest+' sec':a.steps[a.i+1]?esc(P.EX[a.steps[a.i+1].id].name):'Session review'}</h3><p class="tiny muted" style="margin-bottom:0">${rest?'Take longer when needed. The next set never starts without you.':'Repetition-based work uses a stopwatch. You choose when the set is done.'}</p></div></section><div class="notice"><b class="callout-title">Comfort before completion.</b>Stop or change the movement for new or increasing pain. A shorter hold or easier variation still belongs in your log.</div></aside></div>`;
}
function resumeSessionClock(){const a=state.active;if(a?.pausedAt){a.pausedMs+=Date.now()-a.pausedAt;a.pausedAt=null;}}
function pauseWorkout(){if(!state.active)return;if(clock.status==='running'){clock.pause();state.active.pausedAt=Date.now();}else if(clock.status==='paused'){resumeSessionClock();clock.resume();unlockAudio();requestWake();}persist();render();}
function startSet(){const a=state.active,s=step();if(!a||!s||a.stage!=='ready')return;resumeSessionClock();currentInput();a.stage='prep';clock.start(5,'countdown');unlockAudio();requestWake();persist();render();announce('Get ready. Five seconds.');}
function enterWork(){const a=state.active,s=step();if(!a||!s)return;a.stage='work';clock.start(s.seconds||0,s.seconds?'countdown':'stopwatch');cue('start');persist();render();announce(`${currentName(s)}. ${s.side}. Begin.`);}
function readLogInputs(){const a=state.active;if(!a)return true;const rr=$('#actual-reps'),ll=$('#actual-load');if(rr){const v=Number(rr.value);if(!Number.isInteger(v)||v<0||v>1000||rr.value===''){toast('Enter actual repetitions from 0 to 1000.');return false;}a.input.reps=v;}if(ll){if(ll.value==='')a.input.load='';else{const v=Number(ll.value);if(!Number.isFinite(v)||v<0||v>2000){toast('Enter a valid load in kilograms, or leave it blank.');return false;}a.input.load=v;}}return true;}
function completeSet(){const a=state.active,s=step();if(!a||!s||!['work','confirm'].includes(a.stage)||!readLogInputs())return;
 const secs=s.seconds?Math.min(s.seconds,Math.floor(clock.elapsed()/1000)):Math.floor(clock.elapsed()/1000);
 const record={cursor:a.i,id:s.id,name:P.EX[s.id].name,set:s.set,side:s.side,reps:s.seconds?0:Number(a.input.reps??s.reps),seconds:secs,load:a.input.load===''||a.input.load===undefined?null:Number(a.input.load),targetSeconds:s.seconds,targetReps:s.reps,block:s.block,easier:!!a.variations[s.gid],at:new Date().toISOString()};
 a.logs.push(record);a.last=record;a.i++;a.input={};resumeSessionClock();cue('done');
 if(a.i>=a.steps.length){a.stage='finished';clock=new T.Clock();if(!a.pausedAt)a.pausedAt=Date.now();persist();render();showFinish(true);return;}
 if(s.rest){a.stage='rest';clock.start(s.rest);}else{a.stage='ready';clock=new T.Clock();}persist();render();announce(s.rest?'Set saved. Rest.':'Set saved. Next movement ready.');}
function skipRest(){const a=state.active;if(!a||a.stage!=='rest')return;clock=new T.Clock();a.stage='ready';resumeSessionClock();persist();startSet();}
function skipMovement(){if(!state.active||!step())return;if(clock.status==='running')pauseWorkout();const s=step();modal('Skip this movement?',`<p>Remaining sets of <b>${esc(P.EX[s.id].name)}</b> will be marked as skipped, not completed.</p><p class="small muted">Skipping for comfort, equipment or time is fine. The log will stay honest.</p>`,`<button class="btn secondary" data-action="close-modal">Keep movement</button><button class="btn primary" data-action="confirm-skip">Skip movement</button>`);}
function confirmSkip(){const a=state.active,s=step();if(!a||!s)return;a.skipped.push({id:s.id,name:P.EX[s.id].name,gid:s.gid});while(a.i<a.steps.length&&a.steps[a.i].gid===s.gid)a.i++;a.input={};a.last=null;a.stage=a.i>=a.steps.length?'finished':'ready';clock=new T.Clock();closeModal();persist();render();if(a.stage==='finished')showFinish(true);}
function easier(){const a=state.active,s=step();if(!a||!s)return;if(clock.status==='running')pauseWorkout();modal('Use an easier option',`<h3>${esc(P.EX[s.id].name)}</h3><div class="notice"><p>${esc(P.EX[s.id].easier)}</p></div><p class="small muted" style="margin-top:17px">This marks the remaining sets as an easier variation. Reduce repetitions, load or hold duration further when needed. The timer is a guide, not a minimum.</p>`,`<button class="btn secondary" data-action="close-modal">Back</button><button class="btn primary" data-action="confirm-easier">Use easier option</button>`);}
function undoSet(){const a=state.active;if(!a||a.stage!=='rest'||!a.last)return;const prev=a.last;a.logs.pop();a.i=prev.cursor;a.input={cursor:a.i,reps:prev.reps,load:prev.load??''};a.stage='ready';a.last=null;clock=new T.Clock();resumeSessionClock();persist();render();toast('Last set removed. Ready to repeat it.');}
function editLast(){const a=state.active,l=a?.last;if(!l)return;modal('Edit last set',`<p class="small muted">${esc(l.name)} · set ${l.set}${l.side?' · '+l.side:''}</p><div class="fields"><label class="field">${l.targetSeconds?'Seconds performed':'Repetitions performed'}<input id="edit-amount" type="number" min="0" max="1000" value="${l.targetSeconds?l.seconds:l.reps}"></label><label class="field">Load in kg (optional)<input id="edit-load" type="number" min="0" max="2000" step="0.5" value="${l.load??''}" placeholder="Bodyweight"></label></div>`,`<button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-last">Save change</button>`);}
function showFinish(complete){const a=state.active;if(!a)return;finishWasComplete=!!complete;if(clock.status==='running')clock.pause();if(!a.pausedAt)a.pausedAt=Date.now();persist();
 modal(complete?'Session complete':'Finish this session?',`<p>${a.logs.length} confirmed sets · ${T.format(sessionElapsed())} elapsed session time</p><div class="fields"><label class="field">Overall effort<select id="finish-effort"><option value="">Not recorded</option>${[3,4,5,6,7,8,9,10].map(n=>`<option value="${n}">${n} / 10${n===5?' · moderate':n===7?' · challenging':''}</option>`).join('')}</select></label><label class="field">New or increasing discomfort?<select id="finish-discomfort"><option value="">Not recorded</option><option value="no">No</option><option value="yes">Yes</option></select></label></div><label class="field" style="margin-top:16px">Session note (optional)<textarea id="finish-notes" maxlength="1000" placeholder="Variation, equipment, comfort, anything worth remembering."></textarea></label><p class="tiny muted" style="margin-top:12px">${complete?'Skipped movements remain marked as skipped.':'An early finish is saved as a partial session, not a completed workout.'} Next-day response is recorded separately.</p>`,`<button class="btn secondary" data-action="close-modal">Back to session</button><button class="btn primary" data-action="save-session">Save ${complete?'session':'partial session'}</button>`);
}
function saveSession(){const a=state.active;if(!a)return;const notes=$('#finish-notes')?.value||'',effort=$('#finish-effort')?.value||'',discomfort=$('#finish-discomfort')?.value||'';
 const h={id:a.id,date:new Date().toISOString(),localDate:localDate(),week:a.week,day:a.day,title:a.title,type:a.type,readiness:a.readiness,completed:finishWasComplete&&a.i===a.steps.length&&a.skipped.length===0,duration:Math.min(604800,Math.round(sessionElapsed()/1000)),logs:a.logs,skipped:a.skipped,effort:effort?Number(effort):null,discomfort,notes,nextMorning:null};
 if(!state.history.some(x=>x.id===h.id))state.history.push(h);const plannedSets=a.steps.length;publishWorkoutSummary(h,plannedSets);state.active=null;clock=new T.Clock();releaseWake();persist();closeModal();navigate('progress');cue('done');toast(assignedClient?'Session saved and sent to Trainer Admin.':storageOK?'Session saved on this device.':'Session held in this tab. Export a backup now.');}
function renderTimer(){const f=freeConfig,locked=f.started&&freeClock.status!=='finished',paused=freeClock.status==='paused';const busy=!!state.active;
 return pageHeader('A TIMER THAT GETS OUT OF THE WAY','Your rhythm. Your rest.','Use it on its own, or let the guided workout handle each set.')+`<div class="free-timer">${busy?'<div class="notice amber" style="margin-bottom:20px">A guided workout is active. Finish it before starting a separate timer.</div>':''}<section class="card"><div class="timer-tabs">${[['countdown','Countdown'],['stopwatch','Stopwatch'],['intervals','Intervals']].map(([v,l])=>`<button class="choice ${f.mode===v?'selected':''}" data-action="timer-mode" data-value="${v}" aria-pressed="${f.mode===v}" ${locked?'disabled':''}>${l}</button>`).join('')}</div>
 <div class="clock-wrap ${f.mode==='intervals'&&f.segment==='rest'?'rest':''}" id="clock-wrap"><div class="clock-label" id="clock-label">READY</div><div class="clock mono" id="main-clock" role="timer" aria-live="off">01:30</div><div class="clock-note" id="clock-note">Start when you are ready</div><progress class="clock-progress" id="clock-progress" value="0" max="100" aria-label="Timer progress"></progress></div>
 ${f.mode==='countdown'?`<label class="field">Countdown in seconds<input id="free-seconds" type="number" min="1" max="7200" inputmode="numeric" value="${f.seconds}" ${locked?'disabled':''}></label><div class="timer-presets"><button data-action="timer-preset" data-seconds="20" ${locked?'disabled':''}>20s hold</button><button data-action="timer-preset" data-seconds="60" ${locked?'disabled':''}>60s mobility</button><button data-action="timer-preset" data-seconds="90" ${locked?'disabled':''}>90s rest</button><button data-action="timer-preset" data-seconds="120" ${locked?'disabled':''}>2-min rest</button></div>`:''}
 ${f.mode==='intervals'?`<div class="fields" style="grid-template-columns:repeat(3,minmax(0,1fr))"><label class="field">Work (sec)<input id="free-work" type="number" inputmode="numeric" min="5" max="3600" value="${f.work}" ${locked?'disabled':''}></label><label class="field">Rest (sec)<input id="free-rest" type="number" inputmode="numeric" min="0" max="3600" value="${f.rest}" ${locked?'disabled':''}></label><label class="field">Rounds<input id="free-rounds" type="number" inputmode="numeric" min="1" max="50" value="${f.rounds}" ${locked?'disabled':''}></label></div><p class="small muted" style="margin-top:13px">Intervals advance while the app is visible. They never log completed exercises.</p>`:''}
 <div class="workout-controls" style="margin-top:20px"><button class="btn primary big" data-action="free-toggle" ${busy?'disabled':''}>${I(freeClock.status==='running'?'pause':'play')} ${f.pending?'Continue next interval':freeClock.status==='running'?'Pause':paused?'Resume':freeClock.status==='finished'?'Start again':'Start timer'}</button><div class="secondary-controls"><button class="btn secondary" data-action="free-reset">${I('reset')} Reset</button><button class="btn secondary" data-action="test-sound">${I('sound')} Test sound</button></div></div><p class="footer-note">Keep the app visible for alerts. On return from an interruption, elapsed time is reconciled; missed intervals wait for your confirmation rather than silently skipping ahead.</p></section><div class="notice" style="margin-top:19px">${I('info')} Repetition-based strength exercises are not forced into a countdown. In guided workouts, you finish the set and then the rest timer begins.</div></div>`;
}
function captureFreeFields(){const f=freeConfig;function read(sel,min,max,field){const e=$(sel);if(!e)return true;const n=Number(e.value);if(e.value===''||!Number.isInteger(n)||n<min||n>max){toast(`Enter ${field} from ${min} to ${max}.`);e.focus();return false;}f[field==='seconds'?'seconds':field]=n;return true;}
 return f.mode==='countdown'?read('#free-seconds',1,7200,'seconds'):f.mode==='intervals'?read('#free-work',5,3600,'work')&&read('#free-rest',0,3600,'rest')&&read('#free-rounds',1,50,'rounds'):true;}
function startFree(){const f=freeConfig;if(state.active){toast('Finish your guided workout first.');return;}if(f.pending){f.pending=false;advanceFree();persist();render();return;}
 if(freeClock.status==='running'){freeClock.pause();persist();render();return;}
 if(freeClock.status==='paused'){freeClock.resume();unlockAudio();requestWake();persist();render();return;}
 if(!captureFreeFields())return;f.round=1;f.segment='work';f.started=true;f.pending=false;f.done=false;freeClock.start(f.mode==='countdown'?f.seconds:f.mode==='intervals'?f.work:0,f.mode==='stopwatch'?'stopwatch':'countdown');unlockAudio();requestWake();persist();render();}
function advanceFree(){const f=freeConfig;if(f.mode!=='intervals')return;
 if(f.segment==='work'&&f.round>=f.rounds){f.done=true;f.pending=false;releaseWake();cue('done');persist();render();announce('Interval session finished.');return;}
 if(f.segment==='work'&&f.rest>0){f.segment='rest';freeClock.start(f.rest);}else{f.segment='work';f.round++;freeClock.start(f.work);}cue('done');persist();render();}
function resetFree(){freeConfig.started=false;freeConfig.pending=false;freeConfig.done=false;freeConfig.round=1;freeConfig.segment='work';freeClock=new T.Clock();releaseWake();persist();render();}
function renderLibrary(){const entries=Object.values(P.EX).filter(e=>libraryFilter==='all'||e.group===libraryFilter);return pageHeader('45 MOVEMENTS / SIMPLE TECHNIQUE CUES','Know the movement.','Each card includes setup, key cues, a comfort check and an easier option.')+`<div class="searchbar"><label class="field">Find a movement<input type="search" id="exercise-search" placeholder="Try squat, compression, shoulder…" autocomplete="off"></label></div><div class="timer-tabs">${['all','Strength','Skill','Mobility','Movement','Flexibility'].map(t=>`<button class="choice ${libraryFilter===t?'selected':''}" data-action="library-filter" data-value="${t}">${t==='all'?'All':t}</button>`).join('')}</div><div class="library-grid" id="library-grid">${entries.map(e=>`<button class="exercise-card" data-action="exercise" data-id="${e.id}" data-search="${esc((e.name+' '+e.group+' '+e.cues.join(' ')).toLowerCase())}"><div class="between"><span class="eyebrow accent">${e.group}</span>${I('arrow')}</div><h3>${esc(e.name)}</h3><p class="equipment">${esc(e.equipment)}</p><div class="row">${e.tags.map(t=>`<span class="pill">${t}</span>`).join('')}${e.advanced||e.impact?'<span class="pill amber">Optional · readiness first</span>':''}</div></button>`).join('')}</div><div id="no-exercises" class="empty" hidden>No movements match that search.</div>`;}
function renderProgress(){const s=totalStats(),recent=recentStats(),dates=Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-13+i);return d;});
 const amin=state.aerobic.filter(a=>Date.now()-Date.parse(a.date+'T12:00:00')<=7*86400000&&Date.now()>=Date.parse(a.date+'T00:00:00')).reduce((n,a)=>n+a.minutes,0);
 return pageHeader('YOUR RECORD, NOT A SCORECARD','Progress you can trust.','Only confirmed work is recorded. No invented tissue-health scores.')+`<div class="stat-grid" style="margin-bottom:22px"><div class="stat"><div class="number mono">${s.sessions}</div><div class="caption">Completed main sessions</div></div><div class="stat"><div class="number mono">${s.sets}</div><div class="caption">Working sets logged</div></div><div class="stat"><div class="number mono">${s.minutes}</div><div class="caption">Session minutes including rest</div></div></div><div class="cols"><div class="stack"><section class="card"><div class="section-head"><h2>Keep showing up</h2><span class="small muted">Last 14 days</span></div><div class="history-grid">${dates.map(d=>{const hit=state.history.some(h=>h.localDate===localDate(d));return `<div class="history-day ${hit?'filled':''}" title="${d.toLocaleDateString('en-AU')}: ${hit?'session logged':'no session'}">${d.getDate()}</div>`;}).join('')}</div><p class="small muted" style="margin:0">${recent.length} session${recent.length===1?'':'s'} logged in the last 7 days. Rest days are part of the plan, not broken streaks.</p></section><section class="card"><div class="section-head"><h2>Session history</h2><button class="btn text small" data-action="export">Export ${I('download')}</button></div>${state.history.length?[...state.history].reverse().map(h=>`<article class="history-entry"><div class="between"><div class="grow"><h3>${esc(h.title)}</h3><div class="entry-meta">${dateLabel(h.date)} · week ${h.week} · ${Math.round(h.duration/60)} min · ${h.logs.length} logged sets</div></div><span class="pill ${h.completed?'green':'amber'}">${h.completed?'Complete':'Partial'}</span></div>${h.notes?`<p class="small muted" style="margin:12px 0 0">${esc(h.notes)}</p>`:''}${h.discomfort==='yes'?'<p class="small" style="color:var(--amber);margin-top:10px">Discomfort recorded. Review before progressing.</p>':''}<div class="between" style="margin-top:9px"><span class="tiny muted">Next day: ${h.nextMorning?esc(h.nextMorning):'not recorded'}</span><button class="btn text small" data-action="checkin" data-id="${esc(h.id)}">${h.nextMorning?'Update':'Next-day check'}</button></div><details><summary>View sets and variations</summary>${h.logs.map(l=>`<div class="history-log"><div>${esc(l.name)}${l.side?' · '+esc(l.side):''}<br><span class="tiny muted">Set ${l.set}${l.easier?' · easier option':''}</span></div><span class="mono">${l.targetSeconds?l.seconds+'s':l.reps+' reps'}${l.load!==null?' / '+l.load+'kg':''}</span></div>`).join('')}${(h.skipped||[]).map(l=>`<p class="small muted" style="margin-top:10px">Skipped: ${esc(l.name)}</p>`).join('')}<button class="btn text small" data-action="delete-session" data-id="${esc(h.id)}">Delete this record</button></details></article>`).join(''):`<div class="empty">${I('progress')}<h3>Your first session starts the record.</h3><p class="small">No sample results. Your completed sets and notes will appear here.</p><button class="btn primary" data-action="nav" data-view="today">Go to today ${I('arrow')}</button></div>`}</section></div><aside class="stack"><section class="card"><p class="eyebrow accent">THE HEART AND LUNGS COUNT TOO</p><h2>${amin} min</h2><p class="small muted">Aerobic activity logged in the last 7 days.</p><button class="btn secondary full" data-action="log-aerobic">${I('plus')} Log walk, cycle or cardio</button><p class="footer-note">WHO adult guidance includes 150–300 minutes of moderate aerobic activity or 75–150 vigorous minutes per week, plus strengthening on at least two days. Build towards an appropriate amount gradually. This raw log does not convert intensity or judge your health.</p></section><section class="card"><p class="eyebrow accent">REPEATABLE BENCHMARKS</p><h2>Compare like with like.</h2><p class="small muted">Record the variation, conditions and comfortable result. No maximum tests required.</p><button class="btn secondary full" data-action="benchmark">${I('plus')} Add a benchmark</button>${state.benchmarks.slice(-6).reverse().map(b=>`<div class="history-entry"><h3>${esc(b.name)}</h3><span class="small muted">${esc(b.result)} · ${esc(b.date)}</span></div>`).join('')}</section><div class="notice"><b class="callout-title">Before a harder progression</b>Look for repeatable technique and a settled next-day response across multiple sessions. Logs support a decision; they do not certify readiness or diagnose an injury.</div></aside></div>`;
}
function showCheckin(id){const h=state.history.find(h=>h.id===id);if(!h)return;modal('Next-day response',`<p class="small muted">${esc(h.title)} · ${dateLabel(h.date)}</p><p>Compared with before the workout, how do your usual movement and comfort feel?</p><div class="stack">${['Same or better','More sore than usual','New or worsening pain'].map(v=>`<button class="btn secondary" data-action="save-checkin" data-id="${esc(id)}" data-value="${v}">${v}</button>`).join('')}</div><p class="small muted" style="margin-top:18px">More soreness is not automatically an injury. New or increasing pain is a reason to stop the provoking work and seek assessment if persistent or concerning.</p>`);}
function toggleRow(key,title,note){const on=state.settings[key];return `<div class="toggle-row"><div class="grow"><strong class="small">${title}</strong><p>${note}</p></div><button class="toggle ${on?'on':''}" data-action="setting-toggle" data-key="${key}" role="switch" aria-checked="${on}" aria-label="${title}"><span class="toggle-track"></span></button></div>`;}
function renderSettings(){return pageHeader('MAKE IT YOURS','Less friction. More movement.','Workout controls, privacy, progression choices and evidence.')+`<div class="cols-equal"><div class="stack"><section class="card"><h2>Workout-friendly controls</h2>${toggleRow('sound','Sound cues','Sound starts only after a tap. Test it before training.')}${toggleRow('haptics','Vibration cues','Optional. Not supported by every phone or browser.')}${toggleRow('wake','Keep screen awake','Requested during workouts when browser and device permit.')}${toggleRow('large','Larger reading text','More space for cues and labels.')}<label class="field" style="margin-top:19px">Cue volume <span id="volume-label">${Math.round(state.settings.volume*100)}%</span><input id="volume" type="range" min="0" max="100" value="${Math.round(state.settings.volume*100)}"></label><button class="btn secondary full" data-action="test-sound">${I('sound')} Test sound now</button><div class="notice" style="margin-top:16px"><b class="callout-title">Device status</b>Audio: ${('AudioContext'in window||'webkitAudioContext'in window)?'API available; audibility needs your test':'not available'}<br>Vibration: ${'vibrate'in navigator?'API detected; not a guarantee of physical vibration':'not supported'}<br>Screen-on: ${wakeSentinel?'active':'wakeLock'in navigator?'available; not currently active':'not supported here'}</div></section><section class="card"><h2>Training preferences</h2><div class="fields"><label class="field">Session budget<select id="budget"><option value="45" ${state.settings.budget===45?'selected':''}>45 minutes</option><option value="60" ${state.settings.budget===60?'selected':''}>60 minutes</option></select></label><label class="field">Equipment<select id="equipment"><option value="gym" ${state.settings.equipment==='gym'?'selected':''}>Gym / secure bar</option><option value="home" ${state.settings.equipment==='home'?'selected':''}>Minimal kit / band + weights</option></select></label></div><p class="tiny muted" style="margin-top:14px">Estimates include prescribed rests, not equipment delays. Finish early or extend rest whenever needed. Do not rush to fit the budget.</p>${toggleRow('experienced','Previously practised skill options','Off by default. Familiar supported variations only, with readiness confirmation.')}${toggleRow('impact','Optional low-impact jumping','Off by default. Only with comfortable prior impact experience and appropriate assessment.')}<p class="tiny muted" style="margin-top:15px">Changes apply to new sessions. An active workout retains its current plan.</p><button class="btn secondary full" data-action="nav" data-view="programme">Choose two skill priorities ${I('arrow')}</button></section></div><div class="stack"><section class="card"><h2>Your data & privacy</h2><p class="small muted">Workout controls and temporary state are stored locally for reliability. When signed in to a connected deployment, assigned programmes and workout summaries may also sync securely to your coaching account. Human Movement OS does not require advertising analytics or external AI calls for its core coaching intelligence.</p><div class="button-grid"><button class="btn secondary" data-action="export">${I('download')} Export backup</button><button class="btn secondary" data-action="import">Import backup</button></div><p class="tiny muted" style="margin-top:12px">Local backups contain settings, history, benchmarks and cardio entries. Active timers are not imported. Treat backups as personal information.</p><p class="tiny muted"><a href="privacy.html">Privacy notice</a> · <a href="safety.html">Training safety</a> · <a href="terms.html">Terms</a></p><button class="linkbutton small" data-action="export-raw">Export raw saved data</button><div class="sep"></div><button class="btn danger full" data-action="clear-data">Clear this app's data</button></section><section class="card"><h2>Using it as an app</h2><p class="small muted">This build is a self-contained browser application. Some in-chat attachment previews do not execute JavaScript.</p><p class="small muted">The packaged PWA can be installed from an HTTPS deployment. On iPhone, open that hosted app in Safari and use Add to Home Screen. Open it online once before relying on offline use.</p><div class="notice amber">Phone-locked alarms and background audio are not guaranteed. Keep the workout visible; screen-on requests can be refused by the device. No native app-store release is claimed.</div><p class="tiny muted" style="margin-top:15px">The source package includes deployment instructions. This build has not been published to your main website.</p></section></div></div><section class="card sources" style="margin-top:22px"><h2>Evidence and boundaries</h2><p class="small muted">The 52-week structure is an authored training framework, not a clinically validated protocol. Tissues cannot be given a reliable health score from exercise completion. Fascia is not treated as a separate system requiring special diagnostic claims.</p><p class="small muted">Programme revisions keep advanced skills optional, reduce automatic load stacking, retain easier variations, and make recovery repeatable. Calendar progression is never a guarantee of a handstand, lever, planche, flag or one-arm skill.</p>${P.SOURCES.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p>${esc(s.note)}</p>`).join('')}<p class="footer-note">Sources checked 26 September 2026. For persistent pain, injury, known low bone density or uncertainty about heavy, impact or inverted exercise, consult an appropriately qualified clinician or exercise professional.</p></section><p class="version-line">DE-OMEGA-POINT · Human Movement OS · v1.0.0<br>Text-only branding in this build. The locked official logo has not been redrawn.</p>`;}
function showGate(key){const impact=key==='impact';modal(impact?'Optional impact preparation':'Previously practised skill options',`<p>${impact?'This enables brief low two-foot pogos in selected, non-deload sessions. It does not enable sprints, broad jumps or high-volume plyometrics.':'This enables a familiar wall-handstand or assisted tuck-lever option after the foundation phase. It does not unlock full planches, one-arm eccentrics or one-arm handstands.'}</p><label class="check-row"><input id="gate-experience" type="checkbox"><span>${impact?'I already tolerate low-level impact comfortably and have no current lower-limb pain.':'I have already practised the selected supported skill comfortably, with reliable setup and a safe exit.'}</span></label><label class="check-row"><input id="gate-context" type="checkbox"><span>I will use appropriate coaching or clinical assessment for injury, fracture risk, inversion concerns or uncertainty, rather than rely on this switch as clearance.</span></label><p class="tiny muted">These confirmations are your training choice, not a medical or coaching assessment by the app.</p>`,`<button class="btn secondary" data-action="close-modal">Keep foundations</button><button class="btn primary" data-action="confirm-gate" data-key="${key}">Enable optional variations</button>`);}
async function unlockAudio(){if(!state.settings.sound)return false;try{if(!audio){const C=window.AudioContext||window.webkitAudioContext;if(!C)return false;audio=new C();}if(audio.state==='suspended')await audio.resume();return audio.state==='running';}catch(e){return false;}}
async function cue(type='done',force=false){if(state.settings.haptics&&navigator.vibrate){try{navigator.vibrate(type==='done'?[100,60,100]:70);}catch(e){}}
 if(!state.settings.sound&&!force)return;try{const ok=await unlockAudio();if(!ok)return;const at=audio.currentTime;const gain=audio.createGain();gain.connect(audio.destination);const volume=Math.max(.001,state.settings.volume*.32);gain.gain.setValueAtTime(.001,at);gain.gain.exponentialRampToValueAtTime(volume,at+.02);gain.gain.exponentialRampToValueAtTime(.001,at+.45);const o=audio.createOscillator();o.type='sine';o.frequency.setValueAtTime(type==='start'?660:880,at);o.frequency.setValueAtTime(type==='start'?880:660,at+.18);o.connect(gain);o.start(at);o.stop(at+.46);o.onended=()=>{o.disconnect();gain.disconnect();};}catch(e){}}
async function testSound(){state.settings.sound=true;persist();await unlockAudio();cue('done',true);render();toast('Test cue requested. Confirm you can hear it on this device.');}
function wakeNeeded(){return state.settings.wake&&(!!state.active||freeConfig.started&&freeClock.status==='running');}
async function requestWake(){if(!wakeNeeded()||document.visibilityState!=='visible'||!navigator.wakeLock||wakeSentinel||wakePending)return;wakePending=true;try{const sentinel=await navigator.wakeLock.request('screen');if(!wakeNeeded()){await sentinel.release();return;}wakeSentinel=sentinel;sentinel.addEventListener('release',()=>{if(wakeSentinel===sentinel)wakeSentinel=null;paintWake();});}catch(e){}finally{wakePending=false;paintWake();}}
async function releaseWake(){if(wakeSentinel){const s=wakeSentinel;wakeSentinel=null;try{await s.release();}catch(e){}}paintWake();}
function paintWake(){const e=$('#wake-status');if(e)e.textContent='Screen-on: '+(wakeSentinel?'active':'not active');}
function paintClock(){const node=$('#main-clock');if(!node)return;let c=null,label='',note='',ms=0,progress=0,roundUp=true;
 if(view==='workout'&&state.active){const a=state.active,s=step();if(!s)return;c=clock;
  if(a.stage==='ready'){label=s.side?`${s.side} SIDE · READY`:'READY';ms=s.seconds*1000;note=s.seconds?'Start the movement when ready':'Reps are self-paced. Tap start, then set done.';}
  else if(a.stage==='prep'){label=c.status==='paused'?'PAUSED':'GET READY';ms=c.remaining();note='Set your position. The timer starts after this countdown.';}
  else if(a.stage==='rest'){label=c.status==='paused'?'REST PAUSED':'REST';ms=c.remaining();note='Take longer when needed. No automatic next set.';}
  else if(a.stage==='confirm'){label='TIME COMPLETE';ms=0;note='Confirm what you did. Nothing has been logged yet.';}
  else {label=c.status==='paused'?'PAUSED':s.seconds?'HOLD / MOVE':'SET IN PROGRESS';ms=c.remaining();roundUp=c.mode!=='stopwatch';note=s.seconds?'Stop early if position or comfort changes.':'Count your reps. Tap set done when you finish.';}
  progress=c.mode==='countdown'&&c.durationMs>0?Math.min(100,c.elapsed()/c.durationMs*100):0;const se=$('#session-elapsed');if(se)se.textContent='Session '+T.format(sessionElapsed());
 }else if(view==='timer'){const f=freeConfig;c=freeClock;if(!f.started){ms=(f.mode==='stopwatch'?0:f.mode==='intervals'?f.work:f.seconds)*1000;label='READY';note=f.mode==='intervals'?`${f.rounds} rounds · ${f.work}s work / ${f.rest}s rest`:'Tap start when you are ready.';}
 else{ms=c.remaining();roundUp=c.mode!=='stopwatch';label=f.pending?'INTERVAL COMPLETE':c.status==='paused'?'PAUSED':c.status==='finished'?f.mode==='intervals'?'SESSION COMPLETE':'TIME COMPLETE':f.mode==='intervals'?f.segment.toUpperCase():f.mode==='stopwatch'?'ELAPSED':'COUNTDOWN';note=f.pending?'You were away. Continue the next interval when ready.':f.mode==='intervals'?`Round ${f.round} of ${f.rounds}`:'Keep the app visible for alerts.';}
 progress=c.mode==='countdown'&&c.durationMs>0&&f.started?Math.min(100,c.elapsed()/c.durationMs*100):0;
 }else return;
 node.textContent=T.format(ms,roundUp);$('#clock-label').textContent=label;$('#clock-note').textContent=note;$('#clock-progress').value=progress;
}
function tick(){const now=Date.now();if(state.active&&clock.status==='running'){const a=state.active;const due=clock.startedAt+Math.max(0,clock.durationMs-clock.carriedMs);if(clock.tick(now)){
  if(a.stage==='prep'){if(document.hidden||now-due>1800){a.stage='ready';clock=new T.Clock();persist();render();toast('Preparation elapsed while away. Tap start when ready.');}else enterWork();}
  else if(a.stage==='work'){a.stage='confirm';persist();render();if(!document.hidden)cue('done');announce('Time complete. Confirm set done.');}
  else if(a.stage==='rest'){a.stage='ready';clock=new T.Clock();persist();render();if(!document.hidden)cue('done');announce('Rest finished. Start the next set when ready.');}
 }}
 if(freeConfig.started&&freeClock.status==='running'){const due=freeClock.startedAt+Math.max(0,freeClock.durationMs-freeClock.carriedMs);if(freeClock.tick(now)){
  if(freeConfig.mode==='intervals'){if(document.hidden||now-due>1800){freeConfig.pending=true;persist();render();}else advanceFree();}
  else{freeConfig.done=true;persist();render();if(!document.hidden)cue('done');releaseWake();announce('Timer complete.');}
 }}paintClock();paintWake();}
function download(filename,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportBackup(){const output={schema:KEY,version:1,exportedAt:new Date().toISOString(),week:state.week,day:state.day,settings:state.settings,history:state.history,benchmarks:state.benchmarks,aerobic:state.aerobic};download(`movement-os-backup-${localDate()}.json`,JSON.stringify(output,null,2));toast('Backup exported. Keep it somewhere private.');}
async function importFile(file){if(!file)return;if(file.size>5*1024*1024){toast('Backup is too large. Maximum size is 5 MB.');return;}try{const data=JSON.parse(await file.text());if(data.schema!==KEY||data.version!==1||!validHistory(data.history))throw Error('Invalid schema');
 if(data.benchmarks!==undefined&&(!Array.isArray(data.benchmarks)||data.benchmarks.length>500||!data.benchmarks.every(b=>b&&typeof b.name==='string'&&b.name.length<=120&&typeof b.result==='string'&&b.result.length<=300&&typeof b.date==='string')))throw Error('Invalid benchmarks');
 if(data.aerobic!==undefined&&(!Array.isArray(data.aerobic)||data.aerobic.length>2000||!data.aerobic.every(x=>x&&typeof x.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&Number.isFinite(x.minutes)&&x.minutes>=1&&x.minutes<=1440)))throw Error('Invalid cardio');
 pendingImport=data;modal('Restore this backup?',`<p>${data.history.length} saved sessions will replace the current history and settings on this browser.</p><p class="small muted">The current data will not be merged. Active timers and workouts are not imported. Export your current data first when needed.</p>`,`<button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-import">Replace with backup</button>`);
 }catch(e){toast('That file is not a valid Movement OS backup. Nothing was changed.');}}
function restoreImport(){if(!pendingImport)return;if(state.active){toast('Finish your active workout before restoring a backup.');return;}const d=pendingImport;state={...defaults(),week:P.week(d.week).number,day:P.DAYS.some(x=>x.id===d.day)?d.day:'mon',settings:normaliseSettings(d.settings),history:d.history,benchmarks:d.benchmarks||[],aerobic:d.aerobic||[]};storageOK=true;storageError='';freeConfig={mode:'countdown',seconds:90,work:30,rest:60,rounds:5,round:1,segment:'work',started:false,pending:false};clock=new T.Clock();freeClock=new T.Clock();pendingImport=null;previewWeek=state.week;selectedPhase=P.week(state.week).phase;releaseWake();persist();closeModal();navigate('progress');toast('Backup restored.');}
function useWeek(n){if(assignedClient){toast('Your trainer controls the assigned week.');previewWeek=assignedClient.week;selectedPhase=P.week(assignedClient.week).phase;render();return;}if(state.active){toast('Finish the active workout before changing your training week.');return;}n=P.week(n).number;if(n===state.week){state.readiness='ready';persist();toast('Keep this week. Nothing needs to advance.');return;}
 modal(`Use week ${n}?`,`<p><b>${esc(P.week(n).title)}</b></p><p class="small muted">Choosing a week changes the training template, not your skill readiness. Your selected skill regressions stay in place. Returning to an earlier week is always available.</p>${n>state.week?'<label class="check-row"><input id="week-ack" type="checkbox"><span>I will keep familiar variations and repeat or reduce the work when technique or recovery calls for it.</span></label>':''}`,`<button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary" data-action="confirm-week" data-number="${n}">Use week ${n}</button>`);}
function logAerobic(){modal('Log aerobic activity',`<div class="fields"><label class="field">Date<input id="aerobic-date" type="date" value="${localDate()}" max="${localDate()}"></label><label class="field">Minutes<input id="aerobic-minutes" type="number" inputmode="numeric" min="1" max="1440" value="20"></label></div><label class="field" style="margin-top:16px">Activity<input id="aerobic-name" maxlength="100" placeholder="Brisk walk, easy cycle…"></label>`,`<button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-aerobic">Save activity</button>`);}
function benchmark(){modal('Record a benchmark',`<label class="field">Movement or measure<input id="benchmark-name" maxlength="120" placeholder="Supported handstand, squat, knee-to-wall…"></label><label class="field" style="margin-top:14px">Result and conditions<textarea id="benchmark-result" maxlength="300" placeholder="Example: 3 × 15-second supported pike holds, comfortable, same bench height."></textarea></label><p class="tiny muted" style="margin-top:12px">Record repeatable conditions. This is a personal note, not a diagnostic measurement.</p>`,`<button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn primary" data-action="save-benchmark">Save benchmark</button>`);}
// Delegated controls keep the app lightweight and keyboard accessible.
document.addEventListener('click',async ev=>{
 const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
 if(['complete-set','save-session','start-set','confirm-skip','confirm-import','save-aerobic','save-benchmark'].includes(action)){if(lastAction===action&&Date.now()-lastActionAt<450)return;lastAction=action;lastActionAt=Date.now();}
 switch(action){
 case 'nav':navigate(b.dataset.view);break;
 case 'close-modal':closeModal();break;
 case 'day':state.day=b.dataset.day;persist();render();break;
 case 'readiness':state.readiness=b.dataset.value;persist();render();break;
 case 'phase':selectedPhase=Number(b.dataset.id);previewWeek=P.PHASES[selectedPhase-1].start;render();break;
 case 'preview-week':previewWeek=Number(b.dataset.number);render();break;
 case 'use-week':useWeek(Number(b.dataset.number));break;
 case 'confirm-week':{const n=Number(b.dataset.number);if(n>state.week&&!$('#week-ack')?.checked){toast('Confirm that you will keep appropriate variations.');break;}state.week=n;state.readiness='ready';state.day='mon';previewWeek=n;selectedPhase=P.week(n).phase;persist();closeModal();navigate('today');break;}
 case 'programme-day':showPreview(Number(b.dataset.number),b.dataset.day);break;
 case 'preview':showPreview();break;
 case 'exercise':showExercise(b.dataset.id);break;
 case 'start-workout':requestStart(b.dataset.day);break;
 case 'confirm-start':if(!$('#start-ack').checked){toast('Please confirm the comfort and progression check first.');break;}state.settings.onboarded=true;beginWorkout();break;
 case 'resume-workout':navigate('workout');requestWake();break;
 case 'start-set':startSet();break;
 case 'pause-workout':pauseWorkout();break;
 case 'complete-set':completeSet();break;
 case 'add-rest':if(state.active?.stage==='rest'){clock.extend(30);persist();paintClock();toast('30 seconds added to your rest.');}break;
 case 'skip-rest':skipRest();break;
 case 'skip-movement':skipMovement();break;
 case 'confirm-skip':confirmSkip();break;
 case 'make-easier':easier();break;
 case 'confirm-easier':{const s=step();if(s){state.active.variations[s.gid]=true;persist();closeModal();render();}break;}
 case 'undo-set':undoSet();break;
 case 'edit-last':editLast();break;
 case 'save-last':{const a=state.active,l=a?.last;if(!l)break;const amount=Number($('#edit-amount').value),raw=$('#edit-load').value,load=raw===''?null:Number(raw);if(!Number.isFinite(amount)||amount<0||amount>1000||(load!==null&&(!Number.isFinite(load)||load<0||load>2000))){toast('Enter valid repetitions, seconds and load.');break;}if(l.targetSeconds)l.seconds=amount;else l.reps=amount;l.load=load;const idx=a.logs.findIndex(x=>x.cursor===l.cursor);if(idx>=0)a.logs[idx]={...l};persist();closeModal();render();toast('Set updated.');break;}
 case 'end-early':showFinish(false);break;
 case 'finish':showFinish(b.dataset.complete==='true');break;
 case 'save-session':saveSession();break;
 case 'timer-mode':freeConfig.mode=b.dataset.value;resetFree();break;
 case 'timer-preset':freeConfig.seconds=Number(b.dataset.seconds);persist();render();break;
 case 'free-toggle':startFree();break;
 case 'free-reset':if(freeConfig.started&&freeClock.status==='running')modal('Reset this timer?','<p>The current standalone timer will be cleared. Workout history is not affected.</p>','<button class="btn secondary" data-action="close-modal">Keep timer</button><button class="btn primary" data-action="confirm-reset-timer">Reset timer</button>');else resetFree();break;
 case 'confirm-reset-timer':closeModal();resetFree();break;
 case 'toggle-sound':state.settings.sound=!state.settings.sound;persist();if(state.settings.sound){unlockAudio();cue('start');}render();toast(state.settings.sound?'Sound enabled. Test it before training.':'Sound muted.');break;
 case 'test-sound':testSound();break;
 case 'setting-toggle':{const k=b.dataset.key;if(['impact','experienced'].includes(k)&&!state.settings[k]){showGate(k);break;}state.settings[k]=!state.settings[k];if(k==='sound'&&state.settings[k])unlockAudio();if(k==='wake'){if(state.settings.wake)requestWake();else releaseWake();}persist();render();break;}
 case 'confirm-gate':if(!$('#gate-experience').checked||!$('#gate-context').checked){toast('Confirm both checks or keep foundation options.');break;}state.settings[b.dataset.key]=true;persist();closeModal();render();break;
 case 'skill':{const k=b.dataset.key,a=state.settings.skills;if(a.includes(k)){if(a.length===1){toast('Keep at least one skill priority.');break;}state.settings.skills=a.filter(x=>x!==k);}else{if(a.length>=2){toast('Choose up to two priorities. Deselect one first.');break;}a.push(k);}state.settings.experienced=false;persist();render();break;}
 case 'library-filter':libraryFilter=b.dataset.value;render();break;
 case 'checkin':showCheckin(b.dataset.id);break;
 case 'save-checkin':{const h=state.history.find(x=>x.id===b.dataset.id);if(h){h.nextMorning=b.dataset.value;if(h.nextMorning==='New or worsening pain')state.readiness='rest';else if(h.nextMorning==='More sore than usual')state.readiness='lighter';persist();closeModal();render();toast(h.nextMorning==='New or worsening pain'?'Rest selected. Do not progress provoking work; seek assessment as needed.':'Next-day response saved.');}break;}
 case 'delete-session':modal('Delete this session?','<p>This removes the record from this browser. Export a backup first to keep a copy.</p>',`<button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn danger" data-action="confirm-delete-session" data-id="${esc(b.dataset.id)}">Delete record</button>`);break;
 case 'confirm-delete-session':state.history=state.history.filter(h=>h.id!==b.dataset.id);persist();closeModal();render();break;
 case 'log-aerobic':logAerobic();break;
 case 'save-aerobic':{const mins=Number($('#aerobic-minutes').value),d=$('#aerobic-date').value,n=$('#aerobic-name').value.trim();if(!Number.isInteger(mins)||mins<1||mins>1440||!/^\d{4}-\d{2}-\d{2}$/.test(d)||d>localDate()){toast('Enter a valid date and minutes.');break;}state.aerobic.push({id:uid(),date:d,minutes:mins,name:n||'Aerobic activity'});persist();closeModal();render();break;}
 case 'benchmark':benchmark();break;
 case 'save-benchmark':{const n=$('#benchmark-name').value.trim(),r=$('#benchmark-result').value.trim();if(!n||!r){toast('Add a movement and result first.');break;}state.benchmarks.push({id:uid(),name:n,result:r,date:localDate()});persist();closeModal();render();break;}
 case 'export':exportBackup();break;
 case 'export-raw':try{download(`movement-os-raw-${localDate()}.json`,localStorage.getItem(KEY)||'{}');}catch(e){toast('Saved storage cannot be read. Export the in-memory backup instead.');}break;
 case 'import':if(state.active){toast('Finish your active workout before importing.');break;}$('#import-file').click();break;
 case 'confirm-import':restoreImport();break;
 case 'clear-data':modal('Clear local app data?',`<p>This removes your Movement OS workouts, settings and benchmarks from this browser only. Other websites are not affected.</p><label class="field">Type CLEAR to confirm<input id="clear-confirm" autocomplete="off" placeholder="CLEAR"></label>`,`<button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn danger" data-action="confirm-clear">Clear app data</button>`);break;
 case 'confirm-clear':if($('#clear-confirm').value!=='CLEAR'){toast('Type CLEAR to confirm.');break;}try{localStorage.removeItem(KEY);storageOK=true;storageError='';}catch(e){}state=defaults();clock=new T.Clock();freeConfig={mode:'countdown',seconds:90,work:30,rest:60,rounds:5,round:1,segment:'work',started:false,pending:false};freeClock=new T.Clock();previewWeek=1;selectedPhase=1;releaseWake();persist();closeModal();navigate('today');toast('Movement OS data cleared.');break;
 }
});
document.addEventListener('input',ev=>{const e=ev.target;
 if(e.id==='actual-reps'&&state.active){state.active.input.reps=e.value;persist();}
 if(e.id==='actual-load'&&state.active){state.active.input.load=e.value;persist();}
 if(e.id==='volume'){state.settings.volume=Number(e.value)/100;$('#volume-label').textContent=e.value+'%';persist();}
 if(e.id==='exercise-search'){const q=e.value.trim().toLowerCase();let count=0;$$('#library-grid [data-search]').forEach(card=>{const show=card.dataset.search.includes(q);card.hidden=!show;if(show)count++;});$('#no-exercises').hidden=count>0;}
});
document.addEventListener('change',ev=>{const e=ev.target;if(e.id==='budget'){state.settings.budget=Number(e.value);persist();toast('New-session budget saved.');}if(e.id==='equipment'){state.settings.equipment=e.value;persist();toast('Equipment preference saved.');}if(e.id==='import-file'){importFile(e.files[0]);e.value='';}
 if(['free-seconds','free-work','free-rest','free-rounds'].includes(e.id)){if(captureFreeFields()){persist();paintClock();}}
});
document.addEventListener('keydown',ev=>{if(ev.code!=='Space'||ev.target.closest('button,input,select,textarea,summary,dialog'))return;if(view==='workout'&&state.active){ev.preventDefault();if(state.active.stage==='ready')startSet();else if(['work','rest','prep'].includes(state.active.stage))pauseWorkout();}else if(view==='timer'){ev.preventDefault();startFree();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAt=Date.now();persist();}else{tick();requestWake();if(hiddenAt&&Date.now()-hiddenAt>5000&&(state.active||freeConfig.started))toast('Welcome back. Time reconciled; no exercise sets were completed for you.');hiddenAt=null;}});
window.addEventListener('pagehide',()=>persist());window.addEventListener('online',renderNav);window.addEventListener('offline',renderNav);
$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal'))closeModal();});
render();tick();setInterval(tick,200);
if(state.active)toast('An unfinished workout is saved. Use Resume to continue.');
// Register an offline shell only in the packaged HTTPS/localhost deployment, never in the standalone attachment.
if(!window.MOVEMENT_STANDALONE&&'serviceWorker'in navigator&&/^https?:$/.test(location.protocol)){
 const link=document.createElement('link');link.rel='manifest';link.href='./manifest.webmanifest';document.head.append(link);
 navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});
}
})();
